static void ecdhp521_store_scalar(uint8_t output[66U], const uint64_t words[9U])
{
	size_t i;

	for (i = 0U; i < 66U; ++i)
	{
		output[65U - i] = (uint8_t)(words[i / 8U] >> ((i % 8U) * 8U));
	}
}

static void ecdhp521_precompute(ecdhp521_affine_point table[16U], const ecdhp521_affine_point* point)
{
	ecdhp521_projective_point points[16U];
	ecdhp521_field prefix[16U];
	ecdhp521_field inverse;
	ecdhp521_field zi;
	ecdhp521_field z2;
	ecdhp521_field z3;
	size_t i;

	points[0U] = ecdhp521_projective_from_affine(point);
	points[1U] = ecdhp521_dbl_a_minus_3(&points[0U]);

	for (i = 2U; i < 16U; ++i)
	{
		points[i] = ecdhp521_point_add(&points[i - 1U], &points[0U]);
	}

	prefix[0U] = points[0U].z;

	for (i = 1U; i < 16U; ++i)
	{
		prefix[i] = ecdhp521_mul(&prefix[i - 1U], &points[i].z);
	}

	inverse = ecdhp521_fe_invert2(&prefix[15U]);
	inverse = ecdhp521_mul(&inverse, &prefix[15U]);

	for (i = 16U; i > 0U; --i)
	{
		zi = inverse;

		if (i > 1U)
		{
			zi = ecdhp521_mul(&inverse, &prefix[i - 2U]);
		}

		inverse = ecdhp521_mul(&inverse, &points[i - 1U].z);
		z2 = ecdhp521_square(&zi);
		z3 = ecdhp521_mul(&z2, &zi);
		table[i - 1U].x = ecdhp521_mul(&points[i - 1U].x, &z2);
		table[i - 1U].y = ecdhp521_mul(&points[i - 1U].y, &z3);
	}
}

static bool ecdhp521_exchange(uint8_t output[66U], const uint8_t scalar[66U], const ecdhp521_affine_point* point)
{
	ecdhp521_affine_point table[16U];
	ecdhp521_affine_point selected;
	ecdhp521_projective_point accum;
	ecdhp521_field factors[4U];
	ecdhp521_field inverse;
	ecdhp521_field result;
	uint8_t entropy[304U];
	uint8_t blinded[74U];
	uint32_t digits[118U];
	uint32_t signs[118U];
	uint32_t raw;
	uint32_t carry;
	uint32_t sign;
	uint32_t digit;
	uint64_t diff;
	uint64_t equal;
	size_t i;
	size_t j;
	size_t offset;
	size_t byte;
	size_t shift;
	bool ret;

	ret = qsc_csp_generate(entropy, sizeof(entropy));

	if (ret == true)
	{
		ecdhp521_blind_scalar64(blinded, scalar, entropy);

		for (i = 0U; i < 4U; ++i)
		{
			factors[i] = ecdhp521_field_from_wide_bytes(entropy + 8U + i * 74U);
			ret = ret & (ecdhp521_is_zero(&factors[i]) == 0U);
		}

		if (ret == true)
		{
			ecdhp521_precompute(table, point);
			carry = 0U;

			for (i = 0U; i < 118U; ++i)
			{
				offset = 5U * i;
				byte = offset / 8U;
				shift = offset % 8U;
				raw = (uint32_t)blinded[74U - 1U - byte] >> shift;

				if (shift > 3U && byte + 1U < 74U)
				{
					raw |= (uint32_t)blinded[74U - 2U - byte] << (8U - shift);
				}

				raw = (raw & 31U) + carry;
				sign = (raw + 15U) >> 5U;
				digit = raw - (sign << 5U);
				digits[i] = (digit ^ (0U - sign)) + sign;
				signs[i] = sign;
				carry = sign;
			}

			accum = ecdhp521_projective_identity();

			for (i = 118U; i > 0U; --i)
			{
				if (i != 118U)
				{
					accum = ecdhp521_projective_dbl_n_a_minus_3(&accum, 5U);
				}

				selected.x = ecdhp521_zero();
				selected.y = ecdhp521_zero();

				for (j = 0U; j < 16U; ++j)
				{
					diff = (uint64_t)digits[i - 1U] ^ (uint64_t)(j + 1U);
					equal = UINT64_C(1) ^ ((diff | (UINT64_C(0) - diff)) >> 63U);
					ecdhp521_conditional_assign(&selected.x, equal, &table[j].x);
					ecdhp521_conditional_assign(&selected.y, equal, &table[j].y);
				}

				accum = ecdhp521_point_add_or_sub_mixed(&accum, &selected, signs[i - 1U], true);

				if (i > 118U - 4U)
				{
					ecdhp521_projective_randomize_rep(&accum, &factors[118U - i]);
				}
			}

			inverse = ecdhp521_fe_invert2(&accum.z);
			result = ecdhp521_mul(&accum.x, &inverse);
			ecdhp521_store_scalar(output, result.limbs);
		}
	}

	qsc_memutils_secure_erase(entropy, sizeof(entropy));
	qsc_memutils_secure_erase(blinded, sizeof(blinded));
	qsc_memutils_secure_erase(digits, sizeof(digits));
	qsc_memutils_secure_erase(signs, sizeof(signs));
	qsc_memutils_secure_erase(factors, sizeof(factors));
	qsc_memutils_secure_erase(&selected, sizeof(selected));
	qsc_memutils_secure_erase(&accum, sizeof(accum));
	qsc_memutils_secure_erase(&inverse, sizeof(inverse));
	qsc_memutils_secure_erase(&result, sizeof(result));

	return ret;
}

static int32_t ecdhp521_scalar_status(const uint8_t scalar[66U])
{
	uint64_t words[9U] = { 0U };
	uint64_t borrow;
	uint64_t nonzero;
	size_t i;
	int32_t status;

	for (i = 0U; i < 66U; ++i)
	{
		words[i / 8U] |= (uint64_t)scalar[65U - i] << ((i % 8U) * 8U);
	}

	borrow = 0U;
	nonzero = 0U;

	for (i = 0U; i < 9U; ++i)
	{
		(void)ecdhp521_word_sub(words[i], ECDHP521_N[i], &borrow);
		nonzero |= words[i];
	}

	status = 0;

	if (nonzero == 0U)
	{
		status = -2;
	}
	else if (borrow == 0U)
	{
		status = -3;
	}

	qsc_memutils_secure_erase(words, sizeof(words));

	return status;
}

int32_t qsc_ecdhp521_publickey_from_privatekey(uint8_t* publickey, const uint8_t* privatekey)
{
	int32_t status;

	status = -1;

	if (publickey != NULL)
	{
		qsc_memutils_clear(publickey, 132U);

		if (privatekey != NULL)
		{
			status = ecdhp521_scalar_status(privatekey);

			if (status == 0)
			{
				status = (ecdhp521_publickey_derive(publickey, privatekey, ecdhp521_generator_table, 3136U, false)) ? 0 : -9;
			}
		}
	}

	return status;
}

int32_t qsc_ecdhp521_scalar_multiply(uint8_t* secret, const uint8_t* privatekey, const uint8_t* publickey)
{
	ecdhp521_affine_point point;
	int32_t status;

	status = -1;

	if (secret != NULL)
	{
		qsc_memutils_clear(secret, 66U);

		if (privatekey != NULL && publickey != NULL)
		{
			status = ecdhp521_scalar_status(privatekey);

			if (status == 0)
			{
				if (!(ecdhp521_verify_field_deserialize(&point.x, publickey) && ecdhp521_verify_field_deserialize(&point.y, publickey + 66U)))
				{
					status = -4;
				}
				else if (!(ecdhp521_verify_point_on_curve(&point)))
				{
					status = -5;
				}
				else if (ecdhp521_exchange(secret, privatekey, &point) == false)
				{
					status = -9;
				}
			}
		}
	}

	qsc_memutils_secure_erase(&point, sizeof(point));

	return status;
}

static bool ecdhp521_private_scalar_from_seed(uint8_t scalar[66U], const uint8_t seed[66U])
{
	uint8_t nonzero;
	size_t i;

	scalar[0U] = 0U;
	scalar[1U] = 0U;
	qsc_sha512_compute(scalar + 2U, seed, 66U);
	nonzero = 0U;

	for (i = 2U; i < 66U; ++i)
	{
		nonzero |= scalar[i];
	}

	return nonzero != 0U;
}

bool qsc_ecdhp521_generate_seeded_keypair(uint8_t* publickey, uint8_t* privatekey, const uint8_t* seed)
{
	bool ret;

	ret = false;

	if (publickey != NULL)
	{
		qsc_memutils_clear(publickey, 132U);
	}

	if (privatekey != NULL)
	{
		qsc_memutils_clear(privatekey, 66U);
	}

	if (publickey != NULL && privatekey != NULL && seed != NULL)
	{
		if (ecdhp521_private_scalar_from_seed(privatekey, seed) == true)
		{
			ret = (qsc_ecdhp521_publickey_from_privatekey(publickey, privatekey) == 0);
		}

		if (ret == false)
		{
			qsc_memutils_clear(publickey, 132U);
			qsc_memutils_secure_erase(privatekey, 66U);
		}
	}

	return ret;
}

bool qsc_ecdhp521_generate_keypair(uint8_t* publickey, uint8_t* privatekey, bool (*rng_generate)(uint8_t*, size_t))
{
	uint8_t seed[66U] = { 0U };
	bool ret;

	ret = false;

	if (publickey != NULL)
	{
		qsc_memutils_clear(publickey, 132U);
	}

	if (privatekey != NULL)
	{
		qsc_memutils_clear(privatekey, 66U);
	}

	if (publickey != NULL && privatekey != NULL && rng_generate != NULL)
	{
		if (rng_generate(seed, sizeof(seed)) == true)
		{
			ret = qsc_ecdhp521_generate_seeded_keypair(publickey, privatekey, seed);
		}
	}

	qsc_memutils_secure_erase(seed, sizeof(seed));

	return ret;
}

bool qsc_ecdhp521_key_exchange(uint8_t* secret, const uint8_t* publickey, const uint8_t* privatekey)
{
	uint8_t nonzero;
	size_t i;
	bool ret;

	ret = (qsc_ecdhp521_scalar_multiply(secret, privatekey, publickey) == 0);
	nonzero = 0U;

	if (ret == true)
	{
		for (i = 0U; i < 66U; ++i)
		{
			nonzero |= secret[i];
		}

		ret = (nonzero != 0U);
	}

	return ret;
}

void qsc_p521_public_from_private(uint8_t* publickey, const uint8_t* privatekey)
{
	(void)qsc_ecdhp521_publickey_from_privatekey(publickey, privatekey);
}

void qsc_p521_generate_seeded_keypair(uint8_t* publickey, uint8_t* privatekey, const uint8_t* seed)
{
	(void)qsc_ecdhp521_generate_seeded_keypair(publickey, privatekey, seed);
}

void qsc_p521_generate_keypair(uint8_t* publickey, uint8_t* privatekey, bool (*rng_generate)(uint8_t*, size_t))
{
	(void)qsc_ecdhp521_generate_keypair(publickey, privatekey, rng_generate);
}

bool qsc_p521_key_exchange(uint8_t* secret, const uint8_t* publickey, const uint8_t* privatekey)
{
	return qsc_ecdhp521_key_exchange(secret, publickey, privatekey);
}

